/*
 * Modified by Actuna Sp. z o.o.:
 *   E-01: shared deploy lock (moved from api/flows.js); holdUntil() keeps the lock
 *   until the start of the flows completes (R-43)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The deploy lock: the single lock for operations that change the running
 * flows. Deployments through the Admin API (`POST /flows`, `/flow`), changes
 * of the flows run state (`POST /flows/state`) and project switches run under
 * this lock; a second operation waits until the first one completes.
 *
 * The lock is taken only where an operation enters the runtime (runtime api,
 * project switch) - never in `flows/index.js` - and is not re-entrant: code
 * running under the lock must not call another entry point that takes it.
 *
 * The start of the new flows runs asynchronously to the result of a
 * deployment (the HTTP response does not wait for it). `flows.setFlows`
 * registers the start with `holdUntil()`, so the lock is held until the start
 * completes (contract E-01 step 8, R-43) while the result is returned as before.
 * @module
 */

const Mutex = require('async-mutex').Mutex;
const mutex = new Mutex();

// The promises registered by holdUntil() in the running section, or null
// outside a section
let held = null;

/**
 * Runs `fn` under the deploy lock. The returned promise settles when the
 * promise returned by `fn` settles (or if `fn` throws); the lock is released
 * then, or - if `fn` registered promises with `holdUntil()` - when all of
 * them have settled (resolved or rejected).
 * @param {Function} fn - the function to run; may return a promise
 * @return {Promise} - resolves/rejects with the result of `fn`
 */
async function runExclusive(fn) {
    const release = await mutex.acquire();
    const sectionHeld = held = [];
    const finish = function() {
        held = null;
        if (sectionHeld.length === 0) {
            release();
        } else {
            Promise.allSettled(sectionHeld).then(function() { release() });
        }
    };
    let result;
    try {
        result = await fn();
    } catch (err) {
        finish();
        throw err;
    }
    finish();
    return result;
}

/**
 * Keeps the deploy lock after the running section returns, until `promise`
 * settles. Outside a section it does nothing (for example the start of the
 * flows when the runtime starts).
 * @param {Promise} promise
 */
function holdUntil(promise) {
    if (held) {
        held.push(Promise.resolve(promise));
    }
}

/**
 * Whether the deploy lock is currently held.
 * @return {boolean}
 */
function isLocked() {
    return mutex.isLocked();
}

module.exports = {
    runExclusive,
    holdUntil,
    isLocked
};
